// The bounded.tools mark, embedded (#51).
//
// desk is a Worker, not a static-assets site, so an icon has to live in the
// bundle. These are generated by scripts/make-icons.py from geometry recovered
// from bounded.tools' brand/favicon-32.png — the only asset the site publishes,
// and 32px is far too small for a Home Screen. Regenerate rather than hand-edit.
//
// Full-bleed and opaque: every home screen masks the icon itself (iOS with a
// squircle), so a pre-rounded icon rounds twice and shows pale corners inside
// the mask. The glyph sits in the middle 50%, inside the maskable safe zone.

export const ICON_180 = "";
export const ICON_192 = "";
export const ICON_512 = "";

/** base64 → bytes, once per cold start rather than per request. */
export function iconBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const ICONS = { 180: ICON_180, 192: ICON_192, 512: ICON_512 };
